-- Local-dev / test repair: the CMS content rows that V86's audit-trail seed
-- references by fixed UUID. V86 seeds cms_content_changes rows for the
-- homepage and careers heroes, expecting the corresponding cms_contents rows
-- to exist; a production database created them through the admin CMS, and no
-- migration creates them, so a fresh database failed V86's FK. Payloads match
-- the public copy V86 publishes in the change rows, so a page that reads the
-- slot renders the same content either way.

INSERT INTO cms_contents (id, slot_key, component_type, payload, status, version, created_at, updated_at)
SELECT '80000000-0000-0000-0000-000000000001', 'homepage.hero', 'HERO',
       '{"eyebrow":"Chăm sóc chủ động","title":"Đồng hành cùng sức khỏe gia đình","body":"Đặt lịch khám và tìm hiểu dịch vụ chăm sóc phù hợp với nhu cầu của bạn.","ctaLabel":"Đặt lịch khám","ctaHref":"/dat-lich"}'::jsonb,
       'PUBLISHED', 1, CURRENT_TIMESTAMP - INTERVAL '30 days', CURRENT_TIMESTAMP - INTERVAL '10 days'
WHERE NOT EXISTS (SELECT 1 FROM cms_contents WHERE id = '80000000-0000-0000-0000-000000000001');

INSERT INTO cms_contents (id, slot_key, component_type, payload, status, version, created_at, updated_at)
SELECT '80000000-0000-0000-0000-000000000002', 'careers.hero', 'HERO',
       '{"eyebrow":"Cơ hội nghề nghiệp tại HealthCare","title":"Cùng chăm sóc người bệnh bằng năng lực và sự tử tế","body":"Khám phá môi trường làm việc đề cao an toàn, phối hợp liên chuyên môn và sự phát triển bền vững của mỗi thành viên.","ctaLabel":"Xem vị trí đang tuyển","ctaHref":"/careers#vi-tri-dang-tuyen"}'::jsonb,
       'PUBLISHED', 1, CURRENT_TIMESTAMP - INTERVAL '30 days', CURRENT_TIMESTAMP - INTERVAL '10 days'
WHERE NOT EXISTS (SELECT 1 FROM cms_contents WHERE id = '80000000-0000-0000-0000-000000000002');

INSERT INTO cms_contents (id, slot_key, component_type, payload, status, version, created_at, updated_at)
SELECT '80000000-0000-0000-0000-000000000003', 'careers.body', 'RICH_TEXT',
       '{"title":"Điều chúng tôi mong đợi ở đồng đội","body":"Chúng tôi trân trọng tinh thần học hỏi, giao tiếp rõ ràng và cam kết đặt an toàn của người bệnh lên hàng đầu trong mọi vai trò."}'::jsonb,
       'PUBLISHED', 1, CURRENT_TIMESTAMP - INTERVAL '30 days', CURRENT_TIMESTAMP - INTERVAL '10 days'
WHERE NOT EXISTS (SELECT 1 FROM cms_contents WHERE id = '80000000-0000-0000-0000-000000000003');

INSERT INTO cms_contents (id, slot_key, component_type, payload, status, version, created_at, updated_at)
