-- ---------------------------------------------------------------------------
-- Supplemental governance users (added after the generated catalog block).
--
-- V86 seeds health_question_answers authored by user ...023 and reviewed by
-- user ...0002. On a chain grown against a database that already claimed the
-- demo emails (or in an isolated migration schema), V58's ON CONFLICT (email)
-- upsert keeps a pre-existing id and those UUIDs never come into existence;
-- the health_question_answer_guard trigger then correctly rejects the seed
-- rows. These fixture users make the fresh-database chain match production's
-- governance state. Guarded, idempotent, fixture-only.
-- ---------------------------------------------------------------------------

INSERT INTO users (id, email, password_hash, display_name, status, email_verified, email_verified_at, created_at, updated_at)
SELECT '90000000-0000-0000-0000-000000000023', 'v86-fixture-doctor@healthcare.local', '$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy', 'ThS.BS Trần Thu Hà', 'ACTIVE', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM users WHERE id = '90000000-0000-0000-0000-000000000023');

INSERT INTO user_roles (user_id, role_id)
SELECT '90000000-0000-0000-0000-000000000023', r.id FROM roles r WHERE r.code = 'DOCTOR'
ON CONFLICT DO NOTHING;

INSERT INTO users (id, email, password_hash, display_name, status, email_verified, email_verified_at, created_at, updated_at)
SELECT '90000000-0000-0000-0000-000000000002', 'v86-fixture-reviewer@healthcare.local', '$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy', 'BS Nguyễn Quốc Trọng', 'ACTIVE', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM users WHERE id = '90000000-0000-0000-0000-000000000002');

INSERT INTO user_roles (user_id, role_id)
SELECT '90000000-0000-0000-0000-000000000002', r.id FROM roles r WHERE r.code = 'DOCTOR'
ON CONFLICT DO NOTHING;

-- ---------------------------------------------------------------------------
-- Public-schema visibility for the guard V86 re-pins inside its own script.
--
-- V86 executes `ALTER FUNCTION health_question_answer_guard() SET search_path =
-- public, extensions, pg_catalog` five statements before it seeds
-- health_question_answers, and never restores it. From that point on the guard
-- resolves users / roles / user_roles in PUBLIC even when the chain itself runs
-- in an isolated schema (FlywayMigrationTest). Production cannot hit this: there
-- the migration schema *is* public, and V56 (...0002 = doctor@healthcare.local)
-- and V58 (...023 = doctor@healthcare.com) already hold both authors as active
-- DOCTORs, which is exactly why the same chain succeeds on public.
--
-- align-guard-search-path.sql cannot repair it — that script runs before V86 and
-- V86 overrides it mid-migration. So the read target the guard ends up pinned
-- to has to carry the governance state: provision the same two users in public
-- as well. AbstractIntegrationTest#cleanDatabase() deletes every public user
-- before each test method, which is what makes them absent there.
--
-- Fully qualified, guarded and idempotent: on a public-target run these are
-- no-ops because the unqualified block above already inserted (or V56/V58
-- already owned) the same UUIDs. Fixture-only data; retention in the
-- throwaway Testcontainers database.
-- ---------------------------------------------------------------------------

INSERT INTO public.users (id, email, password_hash, display_name, status, email_verified, email_verified_at, created_at, updated_at)
SELECT '90000000-0000-0000-0000-000000000023', 'v86-fixture-doctor@healthcare.local', '$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy', 'ThS.BS Trần Thu Hà', 'ACTIVE', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM public.users WHERE id = '90000000-0000-0000-0000-000000000023')
ON CONFLICT DO NOTHING;

INSERT INTO public.user_roles (user_id, role_id)
SELECT '90000000-0000-0000-0000-000000000023', r.id FROM public.roles r WHERE r.code = 'DOCTOR'
ON CONFLICT DO NOTHING;

